functions.write_card:
static void write_card(enum card_suit_rank csr, card *c)
{
    c->card = (0U);
    if (csr >= SPADE_ACE && csr <= SPADE_K)
    {
        c->card |= (1U << 5);
    }
    else if (csr >= HEART_ACE && csr <= HEART_K)
    {
        c->card |= (2U << 5);
    }
    else if (csr >= DIAMOND_ACE && csr <= DIAMOND_K)
    {
        c->card |= (3U << 5);
    }
    else if (csr >= CLUB_ACE && csr <= CLUB_K)
    {
        c->card |= (4U << 5);
    }
    switch (csr)
    {
    case SPADE_ACE:
    case HEART_ACE:
    case DIAMOND_ACE:
    case CLUB_ACE:
        c->card |= (1U);
        break;
    case SPADE_2:
    case HEART_2:
    case DIAMOND_2:
    case CLUB_2:
        c->card |= (2U);
        break;
    case SPADE_3:
