        c->card |= (12U);
        break;
    case SPADE_K:
    case HEART_K:
    case DIAMOND_K:
    case CLUB_K:
        c->card |= (13U);
        break;
    }
}

functions.insert_into_collection:
static int insert_into_collection(struct card_collection **head, const card *c, card_sorter sorter)
{
    struct card_collection *col;
    struct card_collection *itr;
    col = malloc(sizeof(*col));
    if (col == ((void *)0))
    {
        destroy_card(&c);
        return 1;
    }
    col->c = c;
    if (*head == ((void *)0))
    {
        col->prev = col;
        col->next = col;
        *head = col;
        return 0;
    }
    itr = *head;
    if (sorter(((void *)0), c, itr->c))
    {
        col->prev = itr->prev;
        col->next = itr;
        itr->prev = col;
        col->prev->next = col;
        *head = col;
        return 0;
    }
    while (itr->next != *head)
    {
        if (sorter(itr->c, c, itr->next->c))
        {
            col->prev = itr;
            col->next = itr->next;
            itr->next = col;
            col->next->prev = col;
            return 0;
        }
        itr = itr->next;
    }
    if (sorter(itr->c, c, ((void *)0)))
    {
        col->prev = itr;
        col->next = *head;
        itr->next = col;
        col->next->prev = col;
        return 0;
    }
    return 0;
}

functions.iterate_collection:
static int iterate_collection(struct card_collection *head, struct card_collection **itr)
{
    if (head == ((void *)0))
    {
        return 0;
    }
    if (*itr == ((void *)0))
    {
        *itr = head;
    }
    else
    {
        *itr = (*itr)->next;
        if (*itr == head)
        {
            *itr = ((void *)0);
        }
    }
    return *itr != ((void *)0);
}

functions.append_into_collection:
static void append_into_collection(struct card_collection **head, struct card_collection *new)
{
    if (*head == ((void *)0))
    {
        new->prev = new;
        new->next = new;
        *head = new;
        return;
    }
    new->prev = (*head)->prev;
    new->next = *head;
    new->prev->next = new;
    new->next->prev = new;
}

functions.detach_from_collection:
static void detach_from_collection(const struct card_collection *entry)
{
    entry->next->prev = entry->prev;
    entry->prev->next = entry->next;
}

functions.destroy_collection_entry:
static void destroy_collection_entry(struct card_collection **entry, payload_freer freer)
{
    if (*entry == ((void *)0))
    {
        return;
    }
    if (freer != ((void *)0))
    {
        freer((void *)&(*entry)->c);
    }
    free((void *)*entry);
    *entry = ((void *)0);
}

functions.remove_from_collection_under_itr:
static void remove_from_collection_under_itr(struct card_collection **head, struct card_collection **entry,
                                             payload_freer freer)
{
    struct card_collection *entry_to_remove = ((void *)0);
    int is_entry_head = (*head == *entry);
    detach_from_collection(*entry);
    entry_to_remove = *entry;
    *entry = (*entry)->prev;
    if (*entry == entry_to_remove)
    {
        *entry = ((void *)0);
    }
    destroy_collection_entry(&entry_to_remove, freer);
    if (is_entry_head && *head != *entry)
    {
        *head = ((*entry == ((void *)0)) ? ((void *)0) : (*entry)->next);
    }
}

functions.destroy_collection:
static void destroy_collection(struct card_collection **col_ptr, payload_freer freer)
{
    struct card_collection *head = *col_ptr;
    struct card_collection *head_next;
    if (head == ((void *)0))
    {
        return;
    }
    head->prev->next = ((void *)0);
    do
    {
        head_next = head->next;
        if (freer != ((void *)0))
        {
            freer((void *)&head->c);
        }
        free(head);
        head = head_next;
    } while (head != ((void *)0));
    *col_ptr = ((void *)0);
}

functions.get_card_suit_rank:
enum card_suit_rank get_card_suit_rank(const card *c)
{
    enum card_suit_rank csr;
    enum card_suit cs = get_card_suit(c);
    enum card_rank cr = get_card_rank(c);
    if (cs == INVALID_SUIT || cr == INVALID_RANK)
    {
        return INVALID_CARD;
    }
    switch (cs)
    {
    case SPADE:
        csr = SPADE_ACE;
        break;
    case HEART:
        csr = HEART_ACE;
        break;
    case DIAMOND:
        csr = DIAMOND_ACE;
        break;
    case CLUB:
        csr = CLUB_ACE;
        break;
    }
    return csr + cr;
}

functions.get_card_rank:
enum card_rank get_card_rank(const card *c)
{
    uint8_t r = (c->card & (0x1FU));
    if (r < (1U) || r > (13U))
    {
        return INVALID_RANK;
    }
    return r - 1;
}

functions.get_card_suit:
enum card_suit get_card_suit(const card *c)
{
    uint8_t s = c->card & (0x7U << 5);
    if (s < (1U << 5) || s > (4U << 5))
    {
        return INVALID_SUIT;
    }
    return (s >> 5) - 1;
}

