        return ((void *)0);
    }
    return c;
}

functions.strtocard:
const card *strtocard(const char *str)
{
    enum card_suit_rank csr;
    size_t char_count = strlen(str);
    if (char_count != 2)
    {
        return ((void *)0);
    }
    switch (toupper(str[0]))
    {
    case 'S':
        csr = SPADE_ACE;
        break;
    case 'H':
        csr = HEART_ACE;
        break;
    case 'D':
        csr = DIAMOND_ACE;
        break;
    case 'C':
        csr = CLUB_ACE;
        break;
    default:
        return ((void *)0);
    }
    if (str[1] >= '2' && str[1] <= '9')
    {
        return create_card(csr + str[1] - '1');
    }
    switch (toupper(str[1]))
    {
    case 'A':
        return create_card(csr);
    case '1':
        if (char_count == 3)
        {
            return create_card(csr + 9);
        }
        else
        {
            return ((void *)0);
        }
    case 'J':
        return create_card(csr + 10);
    case 'Q':
        return create_card(csr + 11);
    case 'K':
        return create_card(csr + 12);
    }
    return ((void *)0);
}

functions.cardtostr:
const char *cardtostr(enum card_suit_rank c)
{
    static const char *s[SUIT_COUNT][RANK_COUNT] = {
        {"SA", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9", "S10", "SJ", "SQ", "SK"},
        {"HA", "H2", "H3", "H4", "H5", "H6", "H7", "H8", "H9", "H10", "HJ", "HQ", "HK"},
        {"DA", "D2", "D3", "D4", "D5", "D6", "D7", "D8", "D9", "D10", "DJ", "DQ", "DK"},
        {"CA", "C2", "C3", "C4", "C5", "C6", "C7", "C8", "C9", "C10", "CJ", "CQ", "CK"},
    };
    if (c < SPADE_ACE || c > CLUB_K)
    {
        return ((void *)0);
    }
    return s[c / RANK_COUNT][c % RANK_COUNT];
}

