functions.strtorank:
enum card_rank strtorank(const char *str)
{
    enum card_rank cr = ACE;
    if (str[0] >= '2' && str[0] <= '9')
    {
        cr += str[0] - '1';
    }
    else
    {
        switch (toupper(str[0]))
        {
        case 'A':
            break;
        case '1':
            if (str[1] == '0')
            {
                cr += 9;
            }
            else
            {
                return INVALID_RANK;
            }
            break;
        case 'J':
            cr += 10;
            break;
        case 'Q':
            cr += 11;
            break;
        case 'K':
            cr += 12;
            break;
        default:
            return INVALID_RANK;
        }
    }
    return cr;
}

