functions.get_max_rank_of_hand:
enum card_rank get_max_rank_of_hand(const card_hand *h)
{
    struct card_collection *itr = ((void *)0);
    enum card_rank cr = INVALID_RANK;
    if (h->len == 0)
    {
        return cr;
    }
    while (iterate_collection(h->cards, &itr))
    {
        enum card_rank this_cr = get_card_rank(itr->c);
        if (cr == INVALID_RANK)
        {
            cr = this_cr;
        }
        else if (this_cr > cr)
        {
            cr = this_cr;
        }
    }
    return cr;
}

