void remove_from_hand(card_hand *h, enum card_suit_rank c)
{
    struct card_collection *itr = ((void *)0);
    while (iterate_collection(h->cards, &itr))
    {
        if (get_card_suit_rank(itr->c) == c)
        {
            remove_from_hand_under_itr(h, &itr, ((void *)0));
        }
    }
}

