}

functions.deal_from_deck:
const card *deal_from_deck(card_deck *d)
{
    unsigned long i;
    unsigned long valid_card_idx;
    unsigned long selected_card_idx;
    card *c;
    if (d->card_count <= 0)
    {
        return ((void *)0);
    }
    selected_card_idx = lrand48() % d->card_count;
    valid_card_idx = 0;
    for (i = 0; i < CARD_COUNT; i++)
    {
        c = &d->cards[i];
        if (get_card_suit_rank(c) == INVALID_CARD)
        {
            if (valid_card_idx == selected_card_idx)
            {
                write_card(i, c);
                d->card_count--;
                break;
            }
            valid_card_idx++;
        }
    }
    return c;
}

functions.strip_card_from_deck:
void strip_card_from_deck(enum card_suit_rank c, card_deck *d)
{
    card *card = &d->cards[c];
    if (get_card_suit_rank(card) == INVALID_CARD)
    {
        write_card(c, card);
        d->card_count--;
    }
}

