functions.duplicated_rank_remover:
static enum itr_action duplicated_rank_remover(unsigned long len, unsigned long pos, const card *c)
{
    static enum card_rank prev_rank;
    enum card_rank curr_rank = get_card_rank(c);
    if (pos == 0)
    {
        prev_rank = curr_rank;
        return CONTINUE;
    }
    if (prev_rank == curr_rank)
    {
        return REMOVE_AND_CONTINUE;
    }
    prev_rank = curr_rank;
    return CONTINUE;
}

functions.length_trimmer:
static enum itr_action length_trimmer(unsigned long len, unsigned long pos, const card *c)
{
    if (pos >= 5)
    {
        return REMOVE_AND_CONTINUE;
    }
    return CONTINUE;
}

functions.card_printer:
static enum itr_action card_printer(unsigned long len, unsigned long pos, const card *c)
{
    printf("%4s", cardtostr(get_card_suit_rank(c)));
    return CONTINUE;
}

functions.get_razz_rank:
static enum card_rank get_razz_rank(card_hand *hand)
{
    enum card_rank r;
    unsigned long cards_count;
    iterate_hand(hand, card_printer);
    iterate_hand(hand, duplicated_rank_remover);
    printf(" -> ");
    iterate_hand(hand, card_printer);
    cards_count = count_cards_in_hand(hand);
    if (cards_count < 5)
    {
        printf("\n");
        return INVALID_RANK;
    }
    iterate_hand(hand, length_trimmer);
    r = get_max_rank_of_hand(hand);
    if (cards_count > 5)
    {
        printf("\t");
    }
    else
    {
        printf("\t\t");
    }
    printf("-> ");
    iterate_hand(hand, card_printer);
    printf(": %2s\n", ranktostr(r));
    return r;
}

functions.strip_deck:
static void strip_deck(card_deck *deck, const struct decided_cards *decided_cards)
{
    int i, end;
    end = decided_cards->my_card_count;
    for (i = 0; i < end; i++)
    {
        strip_card_from_deck(get_card_suit_rank(decided_cards->my_cards[i]), deck);
    }
    end = decided_cards->opponent_card_count;
    for (i = 0; i < end; i++)
    {
        strip_card_from_deck(get_card_suit_rank(decided_cards->opponent_cards[i]), deck);
    }
}

functions.simulate_razz_game:
int simulate_razz_game(const struct decided_cards *decided_cards, unsigned long game_count, void *arg,
                       rank_listener listener)
{
    unsigned long i;
    card_hand *my_hand;
    card_deck *deck;
    my_hand = create_hand(7, sort_card_by_rank);
    if (my_hand == ((void *)0))
    {
        fprintf(stderr, "Cannot create a hand\n");
        return 1;
    }
    for (i = 0; i < game_count; i++)
    {
        deck = create_shuffled_deck();
        if (deck == ((void *)0))
        {
            fprintf(stderr, "Cannot create a shuffled deck\n");
            destroy_deck(&deck);
            return 1;
        }
        strip_deck(deck, decided_cards);
        complete_hand(my_hand, decided_cards, deck);
        listener(arg, get_razz_rank(my_hand));
        reset_hand(my_hand);
        destroy_deck(&deck);
    }
    destroy_hand(&my_hand);
    destroy_deck(&deck);
    return 0;
}
